import React, { Suspense } from 'react';

const MessageForm = React.lazy(() => import('../components/MessageForm'));
const AboutMe = React.lazy(() => import('../components/AboutMe'));

const Contact = () => {
  return (
    <div>
      <Suspense fallback={<div>Loading...</div>}>
      <AboutMe />
     <MessageForm />
 
      </Suspense>
    </div>
  );
};

export default Contact;